import{_ as t,o as i,c as s,j as e,a,aa as p}from"./chunks/framework.BAs_AphD.js";const n="/buildary-help-preview/media/cs/diary/stazenikpodpisu.png",r="/buildary-help-preview/media/cs/diary/stazenikpodpisu2.png",l="/buildary-help-preview/media/cs/diary/podepisovani1.png",d="/buildary-help-preview/media/cs/diary/podepisovani6.png",u="/buildary-help-preview/media/cs/diary/podepisovani5.png",z=JSON.parse('{"title":"Podpis v externí aplikaci","description":"","frontmatter":{"title":"Podpis v externí aplikaci","wiki":"cs:diary:externalappsignature"},"headers":[],"relativePath":"diary/externalappsignature.md","filePath":"diary/externalappsignature.md","lastUpdated":1794209661000}'),m={name:"diary/externalappsignature.md"};function v(c,o,k,g,h,y){return i(),s("div",null,[...o[0]||(o[0]=[e("h1",{id:"podpis-v-externi-aplikaci",tabindex:"-1"},[a("Podpis v externí aplikaci "),e("a",{class:"header-anchor",href:"#podpis-v-externi-aplikaci","aria-label":'Permalink to "Podpis v externí aplikaci"'},"​")],-1),e("p",null,[a("Buildary připraví PDF k podpisu, vy ho podepíšete v jiném programu – například v Adobe Acrobat Readeru nebo PDF-XChange Editoru – a podepsaný soubor nahrajete zpět. Ze všech způsobů podpisu je tento nejpracnější, proto ho volte, jen když k tomu máte zásadní důvod. Pohodlnější možnosti popisují "),e("a",{href:"/buildary-help-preview/diary/signaturesetting"},"Způsoby podpisu"),a(".")],-1),e("p",null,[a("Krok za krokem: "),e("a",{href:"/buildary-help-preview/akademie/nastaveni-podpisu"},"Nastavit, čím podepisuji"),a(" v Akademii.")],-1),e("div",{class:"video"},[e("iframe",{src:"https://www.youtube-nocookie.com/embed/gJc9kiJu69U",title:"Video: Podpis v externí aplikaci",loading:"lazy",allowfullscreen:"",allow:"accelerometer; encrypted-media; gyroscope; picture-in-picture"})],-1),p('<h2 id="zapnout-podpis-v-externi-aplikaci" tabindex="-1">Zapnout podpis v externí aplikaci <a class="header-anchor" href="#zapnout-podpis-v-externi-aplikaci" aria-label="Permalink to &quot;Zapnout podpis v externí aplikaci&quot;">​</a></h2><p>V uživatelském menu zvolte <strong>Nastavení podpisu</strong> a v části <strong>Možnost externí aplikace</strong> vyberte <strong>Externí aplikace</strong>. Jen při tomto nastavení obsahuje stažené PDF <strong>pole pro podpis</strong> – bez něj ho v externím programu nepodepíšete.</p><p>Právní váha podpisu závisí na certifikátu, který v externím programu použijete.</p><h2 id="jak-podepsat" tabindex="-1">Jak podepsat <a class="header-anchor" href="#jak-podepsat" aria-label="Permalink to &quot;Jak podepsat&quot;">​</a></h2><p>Postup je stejný pro den (Denní protokol) i pro Další záznam. Místo tlačítka <strong>Podepsat</strong> máte tlačítka <strong>Stáhnout</strong> a <strong>Nahrát</strong>. Stejné volby najdete i v <strong>Dalších volbách</strong>: <strong>Stáhnout k elektronickému podpisu</strong> a <strong>Nahrát elektronicky podepsaný soubor</strong>.</p><div class="tip custom-block"><p class="custom-block-title">Nejdřív zkontrolujte, pak stahujte</p><p>Než soubor stáhnete, prohlédněte si data v Buildary a opravte případné chyby. Stažením se den nebo záznam dočasně zamkne a do dokončení podpisu ho nikdo nezmění.</p></div><ol><li>Klikněte na <strong>Stáhnout</strong>. Buildary vytvoří PDF (nebo stáhne už vytvořené) a den nebo záznam <strong>dočasně zamkne</strong> – podbarví se žlutě a objeví se zámek.</li></ol><div class="gallery"><figure class="shot"><img src="'+n+'" alt="Další záznam s tlačítkem Stáhnout a volbou Stáhnout k elektronickému podpisu v Dalších volbách" loading="lazy"></figure><figure class="shot"><img src="'+r+'" alt="Dočasně zamknutý záznam se žlutým zámkem a údajem, kdo a kdy ho zamkl" loading="lazy"></figure></div><ol start="2"><li>Soubor otevřete v programu pro podpis PDF, například v Adobe Acrobat Readeru, a klikněte do pole pro podpis.</li></ol><figure class="shot" style="--w:640px;"><img src="'+l+'" alt="PDF v Adobe Acrobat Readeru s vyznačeným polem pro podpis" loading="lazy"></figure><ol start="3"><li>Vyberte certifikát, případně upravte vzhled podpisu, a klikněte na <strong>Podepsat</strong>. Pokud v Acrobat Readeru žádný certifikát nemáte, můžete si vytvořit digitální ID volbou <strong>Konfigurujte nové digitální ID</strong> – takový podpis ale není založený na kvalifikovaném certifikátu.</li><li>Podepsaný soubor uložte. Doporučujeme si na podepsané soubory vytvořit samostatnou složku.</li><li>V Buildary klikněte na <strong>Nahrát</strong> a vyberte podepsaný soubor.</li></ol><figure class="shot" style="--w:760px;"><img src="'+d+'" alt="Dočasně zamknutý záznam s tlačítkem Nahrát a volbou Nahrát elektronicky podepsaný soubor" loading="lazy"></figure><p>Pokud jste soubor nahráli v časovém limitu, uloží se a den nebo záznam se <strong>trvale zamkne</strong> – podbarví se zeleně. Po najetí na zámek uvidíte, kdo a kdy podepsal.</p><figure class="shot" style="--w:760px;"><img src="'+u+'" alt="Podepsaný a zamknutý záznam se zeleným zámkem, jménem podepisujícího a časem podpisu" loading="lazy"></figure><p>Další osoby podepisují stejným postupem – stáhnou už podepsaný soubor, přidají svůj podpis a nahrají ho zpět.</p><h2 id="casovy-limit-pro-podpis" tabindex="-1">Časový limit pro podpis <a class="header-anchor" href="#casovy-limit-pro-podpis" aria-label="Permalink to &quot;Časový limit pro podpis&quot;">​</a></h2><p>Podepsaný soubor musíte nahrát zpět v časovém limitu nastaveném v Nastavení deníku – co se stane, když ho nestihnete, popisuje <a href="/buildary-help-preview/diary/signing#docasny-zamek-a-casovy-limit">Dočasný zámek a časový limit</a>.</p><p>Ostatní pravidla podepisování – pořadí podpisů, navazující dny, kontrolu Dalších záznamů – popisuje <a href="/buildary-help-preview/diary/signing">Podepisování deníku</a>.</p>',18)])])}const j=t(m,[["render",v]]);export{z as __pageData,j as default};
